/**
 * Guards the Mishna Berura Amud Yomi table shipped to the client
 * (generated by scripts/fetch-amudim.mjs): every amud of the cycle is present,
 * the amudim walk through the sefer in order, and each chelek's amudim begin
 * at the siman that chelek begins with.
 */
const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');

function loadClientData() {
  const file = path.join(__dirname, '..', 'client', 'src', 'components', 'charts', 'data', 'mishnaBeruraAmudim.js');
  const source = fs
    .readFileSync(file, 'utf8')
    .replace(/export const (\w+) =/g, 'const $1 = exports.$1 =')
    .replace(/export function (\w+)/g, 'exports.$1 = $1; function $1');
  const sandbox = { exports: {} };
  vm.runInNewContext(source, sandbox);
  return sandbox.exports;
}

const { AMUD_COUNT, amudChalakim, amudInfo, amudLabel, amudRangeForSimanim } = loadClientData();

test('the cycle has 1750 amudim, from 1:1 to the end of Orach Chaim', () => {
  assert.equal(AMUD_COUNT, 1750);
  assert.deepEqual({ ...amudInfo(1) }, { amud: 1, siman: 1, seif: 1, chelek: 'Chelek 1' });
  assert.equal(amudInfo(1750).siman, 697);
  assert.equal(amudInfo(0), null);
  assert.equal(amudInfo(1751), null);
  assert.equal(amudInfo('abc'), null);
});

test('amudim run through the simanim in order, without skipping a siman range backwards', () => {
  let previous = amudInfo(1);
  for (let amud = 2; amud <= AMUD_COUNT; amud++) {
    const info = amudInfo(amud);
    const order = (i) => (i.seif === null ? Infinity : i.seif);
    assert.ok(
      info.siman > previous.siman || (info.siman === previous.siman && order(info) >= order(previous)),
      `amud ${amud} (${info.siman}:${info.seif}) starts before amud ${amud - 1}`
    );
    previous = info;
  }
});

test('chalakim are contiguous and each begins at its first siman', () => {
  // Spread into this realm: objects built inside the vm have a foreign prototype.
  const ranges = Array.from(amudChalakim, (c) => ({ ...c }));
  assert.equal(ranges[0].start, 1);
  assert.equal(ranges[ranges.length - 1].end, AMUD_COUNT);
  for (let i = 1; i < ranges.length; i++) {
    assert.equal(ranges[i].start, ranges[i - 1].end + 1, `${ranges[i].chelek} should follow ${ranges[i - 1].chelek}`);
  }

  const firstSimanim = ranges.map((c) => `${c.chelek} ${amudInfo(c.start).siman}:${amudInfo(c.start).seif}`);
  assert.deepEqual(firstSimanim, [
    'Chelek 1 1:1',
    'Chelek 2 128:1',
    'Chelek 3 242:1',
    'Chelek 4 345:1',
    'Chelek 5 429:1',
    'Chelek 6 530:1'
  ]);
});

test('row labels carry the amud number and where it starts', () => {
  assert.equal(amudLabel(327), '327 · 143:4');
  // Amud 637 is a review day for siman 259, with no se'if of its own.
  assert.equal(amudLabel(637), '637 · 259');
  assert.equal(amudLabel(9999), '9999');
});

const range = (from, to) => ({ ...amudRangeForSimanim(from, to) });

test('a siman range maps to the amudim that cover it', () => {
  // A whole chelek: exactly its amudim.
  assert.deepEqual(range(128, 241), { start: 281, end: 579 });
  assert.deepEqual(range(1, 697), { start: 1, end: AMUD_COUNT });
  // Siman 143 is amudim 326-330 (326 opens at 143:1).
  assert.deepEqual(range(143, 143), { start: 326, end: 330 });
  // Siman 127 begins inside amud 280, which opens at 126:3.
  assert.equal(range(127, 127).start, 280);
  // Se'if 12:1 spans amudim 43 and 44: the range starts at the first.
  assert.equal(range(12, 12).start, 43);
  // Laws of Tzitzit (8-24) ends with the last amud that starts by siman 24.
  const tzitzit = range(8, 24);
  assert.equal(amudInfo(tzitzit.start).siman, 8);
  assert.ok(amudInfo(tzitzit.end).siman <= 24 && amudInfo(tzitzit.end + 1).siman > 24);
  // Nonsense in, nothing out.
  assert.equal(amudRangeForSimanim(20, 10), null);
  assert.equal(amudRangeForSimanim('x', 10), null);
});
